SELECT analytics_budget_facts.department, SUM(analytics_budget_facts.expense_amount) AS expense_amount, SUM(analytics_budget_facts.budget_amount) AS budget_amount, SUM(analytics_budget_facts.budget_variance) AS budget_variance FROM analytics_budget_facts WHERE analytics_budget_facts.year = 2022 AND analytics_budget_facts.month = 4 AND analytics_budget_facts.cost_center = 'cc_017' AND analytics_budget_facts.expense_category = 'expense_04' GROUP BY analytics_budget_facts.department ORDER BY budget_variance DESC, analytics_budget_facts.department ASC LIMIT 15
